import { DomainRoadmapSchema, RoadmapStageSchema, type DomainRoadmap, type RoadmapStage, type TopicLevel } from "@/lib/schema";

const ids = (track: string, values: string[]) => values.map((value) => `${track}/${value}`);
const stage = (
  id: string,
  title: string,
  level: TopicLevel,
  objective: string,
  topicIds: string[],
  prerequisites: string[],
  concepts: string[],
  practice: string[],
  deliverable: string,
  readinessGate: string[],
  interviewPrompts: string[],
  estimatedHours: number
): RoadmapStage => RoadmapStageSchema.parse({ id, title, level, objective, topicIds, technologyIds: [], prerequisites, concepts, practice, deliverable, readinessGate, interviewPrompts, estimatedHours });

const sharedRevision = [
  "Draw the domain map from memory and explain every dependency arrow.",
  "Explain one foundational, one interview-level, and one advanced trade-off without notes.",
  "Rebuild the stage deliverables from a blank repository or blank document.",
  "Answer the roadmap's interview prompts aloud under a five-minute timebox.",
  "Diagnose one deliberately broken example and narrate the evidence used.",
  "State the limits of every analogy before giving the exact mechanism.",
  "Compare two plausible designs and name the workload assumption that changes the choice.",
  "Condense the domain into a one-page sheet of invariants, commands, traps, and checks."
];

